assistantMessageEvent.delta:
Batch, classifySignal } from '/tmp/eval-work-6XTenu/process_batch';

function assertEqual(a: any, b: any, msg: string) {
  if (JSON.stringify(a) !== JSON.stringify(b)) {
    console.error("FAIL", msg, "\n got:", a, "\n exp:", b);
    process.exitCode = 1;
  } else {
    console.log("PASS", msg);
  }
}

const valid = {
  readings: [
    { channel: "A", unit: "mV", value: 10, at: 0 },
    { channel: "A", unit: "mV", value: 700, at: 1 },
    { channel: "B", unit: "V", value: 1, at: 2 },   // ->

    { channel: "B", unit: "mV", value: -5, at: 4 },  // negative
  ]
};

assertEqual(processBatch(null).ok, false, "null invalid");
assertEqual(processBatch({}).ok, false, "empty object invalid");
assertEqual(processBatch({readings: []}).ok, false, "empty readings invalid");
assertEqual(processBatch({readings: undefined}).ok, false, "undef reads invalid");
assertEqual(processBatch(valid).ok, true, "valid ok");

// bad channel
assertEqual(processBatch({readings:[{channel:"", unit:"mV", value:1, at:0}]}).error, "reading 0: bad channel", "bad channel");
assertEqual(processBatch({readings:[{channel:"A", unit:"mV", value:1.5, at:0}]}).error, "reading 0: bad value", "bad value");
assertEqual(processBatch({readings:[{channel:"A", unit:"mV", value:1, at:-1}]}).error, "reading 0: bad timestamp", "bad timestamp");
assertEqual(processBatch({readings:[{channel:"A", unit:"X", value:1, at:0}]}).error, "reading 0: bad unit", "bad unit");
assertEqual(processBatch({readings:[null]}).error, "reading 0: malformed", "malformed");

// too many
const big: any = {readings: []};
for (let i=0;i<501;i++) big.readings.push({channel:"A", unit:"mV", value:1, at:i});
assertEqual(processBatch(big).error, "batch too large", "too large");

const res = processBatch(valid);
