export interface Reading {
  channel: string;
  unit: string;
  value: number;
  at: number;
}

interface ParsedReading {
  channel: string;
  millivolts: number;
  at: number;
}

interface ChannelSummary {
  count: number;
  min: number;
  max: number;
  worst: string;
}

export interface BatchResult {
  ok: boolean;
  error?: string;
  readings?: number;
  labels?: string[];
  channels?: Record<string, ChannelSummary>;
  alerts

?: string[];
  report?: string;
}

// A "page" of readings a device pushes at once.
const MAX_READINGS = 500;
const UNITS = ["uV", "mV", "V"] as const;
type Unit = (typeof UNITS)[number];

// Classification thresholds on millivolts, kept together so the bands are
// easy to reason about and extend.
const STANDBY_MAX = 50;
const IDLE_MAX = 200;
const ACTIVE_MAX = 600;
const LOADED_MAX = 900;

export function processBatch(raw: unknown): BatchResult {
  const batchError = validateBatch(raw);
  if (batchError !== null) {
    return { ok: false, error: batchError };
  }

  const entries = (raw as { readings: unknown[] }).readings;
  const parsed: ParsedReading[] = new Array(entries.length);
  for (let index = 0; index < entries.length; index++) {
    const outcome = parseReading(entries[index], index);
    if (typeof outcome === "string") {
      return { ok: false, error: outcome };
    }
    parsed[index] = {
      channel: outcome.channel,
      millivolts: normalizeValue(outcome.unit, outcome.value),
      at: outcome.at,
    };
  }

  const labels = parsed.map((reading) => classifySignal(reading.m

illivolts));
  const channels = channelSummaries(parsed, labels);
  const alerts = collectAlerts(parsed, labels);
